package com.example.takura.operations.infrastructure;
import io.micrometer.core.instrument.*;import java.time.Clock;import java.util.concurrent.atomic.AtomicLong;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public final class OperationalMetrics{private final JdbcTemplate jdbc;private final Clock clock;private final AtomicLong notificationAge=new AtomicLong();private final AtomicLong scanAge=new AtomicLong();private final AtomicLong backupSuccessEpoch=new AtomicLong();public OperationalMetrics(JdbcTemplate jdbc,Clock clock,MeterRegistry registry){this.jdbc=jdbc;this.clock=clock;Gauge.builder("takura.notification.oldest.seconds",notificationAge,AtomicLong::get).register(registry);Gauge.builder("takura.scan.oldest.seconds",scanAge,AtomicLong::get).register(registry);Gauge.builder("takura.backup.last.success.seconds",backupSuccessEpoch,AtomicLong::get).register(registry);}@Scheduled(fixedDelayString="${takura.telemetry.queue-metric-interval-ms:30000}")public void refresh(){notificationAge.set(age("SELECT min(created_at) FROM takura.notification_outbox WHERE state IN ('PENDING','LEASED','DELIVERY_UNKNOWN','FAILED_REQUIRES_REVIEW')"));scanAge.set(age("SELECT min(created_at) FROM takura.attachment_scan_job WHERE state IN ('PENDING','LEASED','FAILED_REQUIRES_REVIEW')"));}private long age(String sql){java.sql.Timestamp t=jdbc.queryForObject(sql,java.sql.Timestamp.class);return t==null?0:Math.max(0,clock.instant().getEpochSecond()-t.toInstant().getEpochSecond());}}
